        source = doc.metadata["source"]
        checks = [check for check in ignore_documents if check in source]
        if checks:
            return False
        return True

    documents = [doc for doc in knowledge_documents if is_valid_document(doc)]
    logger.info(f"""find_relevant_documents: 
