However, the `selectionStart`, `selectionEnd`, and `setSelectionRange` methods are specific to `HTMLInputElement` and `HTMLTextAreaElement`. Content-editable elements have a different API for managing selections: `window.getSelection()` and `document.createRange()`.

This means the logic needs to be adapted significantly depending on whether you're dealing with an input field/textarea or a content-editable element.

Let's provide a solution that tries to handle both cases, but it's important to note that managing selections in content-editable divs is more complex.

Here's an updated function that attempts to address this, with a focus on `contenteditable` elements:

```javascript
function replaceWordAtCursor(element, newWord) {
  // Ensure the element has focus before proceeding
  element.focus();

  // Check if it's a content-editable element
  if (element.contentEditable === 'true') {
    const selection = window.getSelection();
    if (!selection || selection.rangeCount === 0) {
      return; // No selection or range available
    }

    const range = selection.getRangeAt(0);
    const startOffset = range.startOffset;
    const endOffset = range.endOffset;
    const currentNode = range.startContainer;

    // Get the text content of the node where the cursor is
    const textContent = currentNode.textContent;

    // Find the start and end of the current word within the textContent
    let wordStart = startOffset;
    while (wordStart > 0 && /\s/.test(textContent[wordStart - 1])) {
      wordStart--;
    }
    while (wordStart > 0 && !/\s/.test(textContent[wordStart - 1])) {
      wordStart--;
    }
     // Adjust wordStart if it's at the beginning of the string and not preceded by a space
    if (wordStart > 0 && /\s/.test(textContent[wordStart - 1])) {
        wordStart++;
    }

    let wordEnd = endOffset;
    while (wordEnd < textContent.length && !/\s/.test(textContent[wordEnd])) {
      wordEnd++;
    }

    // If no text is selected, expand selection to the whole word
    if (startOffset === endOffset && startOffset > 0 && startOffset < textContent.length && !/\s/.test(textContent[startOffset - 1]) && !/\s/.test(textContent[startOffset])) {
        range.setStart(currentNode, wordStart);
        range.setEnd(currentNode, wordEnd);
    } else {
        // If there was a selection, ensure it's within the current node
        // This part can get tricky if selection spans multiple nodes.
        // For simplicity, we'll assume selection is within a single text node.
        // If selection spans multiple nodes, this will likely break or need more advanced logic.
    }

    // Replace the selected word
    range.deleteContents(); // Remove the selected content
    const newTextNode = document.createTextNode(newWord);
    range.insertNode(newTextNode); // Insert the new word

    // Move cursor after the new word
    range.setStartAfter(newTextNode);
    range.collapse(true); // Collapse the range to a single point
    selection.removeAllRanges();
    selection.addRange(range);

  } else if (element instanceof HTMLInputElement || element instanceof HTMLTextAreaElement) {
    // Handle Input and Textarea elements (previous logic)
    const startPos = element.selectionStart;
    const endPos = element.selectionEnd;

    // Find the start and end of the current word
    let wordStart = startPos;
    while (wordStart > 0 && /\s/.test(element.value[wordStart - 1])) {
      wordStart--;
    }
    while (wordStart > 0 && !/\s/.test(element.value[wordStart - 1])) {
      wordStart--;
    }
    // Adjust wordStart if it's at the beginning of the string and not preceded by a space
    if (wordStart > 0 && /\s/.test(element.value[wordStart - 1])) {
        wordStart++;
    }

    let wordEnd = endPos;
    while (wordEnd < element.value.length && !/\s/.test(element.value[wordEnd])) {
      wordEnd++;
    }

    // If there's no selection and the cursor is within a word, expand the selection to the whole word
    if (startPos === endPos && startPos > 0 && startPos < element.value.length && !/\s/.test(element.value[startPos - 1]) && !/\s/.test(element.value[startPos])) {
        element.selectionStart = wordStart;
        element.selectionEnd = wordEnd;
    }

    // Replace the selected word (or the word at the cursor) with the new word
    const newValue = element.value.substring(0, element.selectionStart) +
                     newWord +
                     element.value.substring(element.selectionEnd);

    element.value = newValue;

    // Move the cursor to the end of the new word
    const newCursorPos = element.selectionStart + newWord.length;
    element.setSelectionRange(newCursorPos, newCursorPos);

    // Trigger an input event
    element.dispatchEvent(new Event('input', { bubbles: true }));

  } else {
    console.error("The provided element is not an input, textarea, or contentEditable element.");
  }
